-- Official SG past questions: 2017 autumn, selected text-representable morning questions.
-- Source paper and answer key are linked from the official IPA past-exam archive.
-- Image/table-only questions are omitted rather than reconstructed from incomplete image text.
INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-official-h29a-2017-q01','exam-sg','サイバーセキュリティ経営ガイドライン','standard','single_choice','経済産業省とIPAが策定した「サイバーセキュリティ経営ガイドライン（Ver.1.1）」に従った経営者の対応はどれか。','[{"id":"a","text":"緊急時にCISOの独断専行を防ぐため，経営者レベルの権限をもたない者をCISOに任命する。"},{"id":"b","text":"サイバー攻撃が模倣されることを防ぐため，自社への攻撃情報を外部に一切提供しないよう命じる。"},{"id":"c","text":"サイバーセキュリティ人材を確保するため，適切な処遇の維持・改善や予算確保を指示する。"},{"id":"d","text":"取引先に対する監査や対策状況の把握を禁止する。"}]','"c"','正解はウ。経営者は必要な予算と人材を確保し，サイバーセキュリティ対策を経営課題として推進する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_ans.pdf','ja'),
('sg-official-h29a-2017-q04','exam-sg','暗号技術・CRYPTREC','standard','single_choice','CRYPTRECの役割として，適切なものはどれか。','[{"id":"a","text":"外国為替及び外国貿易法で規制される暗号装置の輸出許可申請を審査・承認する。"},{"id":"b","text":"政府調達においてIT関連製品のセキュリティ機能を評価・認証する。"},{"id":"c","text":"電子政府での利用を推奨する暗号技術の安全性を評価・監視する。"},{"id":"d","text":"民間企業のサーバに対する攻撃を監視・検知する。"}]','"c"','正解はウ。CRYPTRECは電子政府推奨暗号の安全性評価・監視などを行う。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_ans.pdf','ja'),
('sg-official-h29a-2017-q05','exam-sg','リスクアセスメント・リスク特定','standard','single_choice','リスクアセスメントのリスク特定で特定する対象だけを全て挙げたものはどれか。対象：(1)リスク対応に掛かる費用，(2)リスクによって引き起こされる事象，(3)その事象の原因及び起こり得る結果，(4)リスクを顕在化させる可能性をもつリスク源。','[{"id":"a","text":"(1)，(2)，(4)"},{"id":"b","text":"(1)，(4)"},{"id":"c","text":"(2)，(3)"},{"id":"d","text":"(2)，(3)，(4)"}]','"d"','正解はエ。リスク特定ではリスク源，リスク事象，原因及び起こり得る結果を発見・記述する。対応費用はリスク特定の対象ではない。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_ans.pdf','ja'),
('sg-official-h29a-2017-q06','exam-sg','リスク対応・リスクファイナンシング','standard','single_choice','リスク対策の手法のうち，リスクファイナンシングに該当するものはどれか。','[{"id":"a","text":"システム被害につながるリスクの発生を抑える対策に資金を投入する。"},{"id":"b","text":"リスクが大きいシステムを廃止し，新たなシステムを構築する。"},{"id":"c","text":"リスクが顕在化した場合の被害を小さくする設備に資金を投入する。"},{"id":"d","text":"リスクによってシステムが被害を受けた場合を想定して保険を掛ける。"}]','"d"','正解はエ。リスクファイナンシングは，損失発生に備えて資金を確保する対応であり，保険は代表例である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_ans.pdf','ja'),
('sg-official-h29a-2017-q07','exam-sg','リスク評価・リスク基準','standard','single_choice','JIS Q 27001:2014に従ったリスク評価で，リスクが受容可能かどうかを判断する際に，リスク分析結果と比較するものはどれか。','[{"id":"a","text":"組織の情報セキュリティインシデントシナリオ"},{"id":"b","text":"組織のインシデント対応フロー"},{"id":"c","text":"組織の情報セキュリティのリスク基準"},{"id":"d","text":"組織の情報セキュリティリスク対応計画"}]','"c"','正解はウ。リスク分析の結果を組織の状況に応じて定めたリスク基準と比較し，受容可能性を判断する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_ans.pdf','ja'),
('sg-official-h29a-2017-q08','exam-sg','リスク管理・リスク所有者','standard','single_choice','JIS Q 27000:2014で，リスクを運用管理することについて，説明責任及び権限をもつ人又は主体を何と呼ぶか。','[{"id":"a","text":"監査員"},{"id":"b","text":"トップマネジメント"},{"id":"c","text":"利害関係者"},{"id":"d","text":"リスク所有者"}]','"d"','正解はエ。リスク所有者は，リスクを運用管理することについて説明責任と権限をもつ人又は主体である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_ans.pdf','ja'),
('sg-official-h29a-2017-q09','exam-sg','脅威・脆弱性・リスク','standard','single_choice','情報セキュリティマネジメントにおける脅威と脆弱性に関する記述のうち，最も適切なものはどれか。','[{"id":"a","text":"管理策の欠如によって脅威が高まり，脆弱性の深刻度が低くなる。"},{"id":"b","text":"脅威が存在しないと判断できる場合，脆弱性に対処する必要性は低い。"},{"id":"c","text":"脅威のうち，脆弱性によってリスクが顕在化するのは環境的脅威である。"},{"id":"d","text":"脆弱性の有無にかかわらず，事故の発生確率は脅威の大きさで決まる。"}]','"b"','正解はイ。脆弱性があっても，それを利用する脅威が存在しなければ，リスクが顕在化する可能性は低い。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_ans.pdf','ja'),
('sg-official-h29a-2017-q10','exam-sg','ISMS・是正処置','standard','single_choice','JIS Q 27000:2014において，不適合が発生した場合にその原因を除去し，再発を防止するためのものはどれか。','[{"id":"a","text":"継続的改善"},{"id":"b","text":"修正"},{"id":"c","text":"是正処置"},{"id":"d","text":"リスクアセスメント"}]','"c"','正解はウ。修正は発見された不適合を除去する処置であり，是正処置は原因を除去して再発を防ぐ処置である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000fqpm-att/2017h29a_sg_am_ans.pdf','ja');
